#define r34(p) fract(12.0 * sin(p.xyzx + p.xyzx) * sin(p.yzxx))
#define r35(p) fract(12.0 * sin(p.yxzy + p.zyzx) * sin(p.yzxy))
#define Q(z) P((z), 0.0, 0.0, 0.0, 9.0, 0.0)
#define P(z, a, b, c, d, e) vec3(sin(z * a) * b, cos(z * c) * d - e, z)

void mainImage(out vec4 O, vec2 u) {
    vec3 p, r = iResolution, C;
    float s, t = iTime * 0.1;

    float i = sin(t) * 30.0;
    float a = abs(sin(t / 2.0));

    O *= 0.0;
    float colorRangeBottom = 1.0 + 1.1 * (sin(t) + 0.001);
    float colorRangeMid = 7.0 + 4.0 * (sin(t) + 0.1);

    float maxDistance = 3e2 + (sin(t) * 2e2) ;
    float forwardSpeed = t * 3.0 + sin(t) * 5.0;

    while (i++ < maxDistance) {
        s = a + forwardSpeed;

        float rotationSpeed = i * (sin(t) + cos(t) - 0.5) * 0.005;

        vec2 uv = (u * 2.0 - r.xy) / r.y;
        p = acos(cos(vec3(uv * a / 10.0 * mat2(cos(vec4(0.0, 11.0, 33.0, 0.0) + rotationSpeed)), s)));

        float j = 0.0;
        while (j++ < 2.0) {
            p = r34(p).xyz;
        }

        p = abs(2.0 * p);
        p = p.x < p.y ? p.zxy : p.zyx;
        p -= vec3(3.0, 5.0, 1.0);

        float colorForce = max(0.02 + abs(sin(t) * 0.091), 0.1);
        C = colorForce * cos(s * 3.14 + vec3(colorRangeBottom, colorRangeMid, 1.0));

        a += s = abs(length(p.xz) / 38.0 - 0.054);

        O.rgb += C * C / exp(i * i / 28.0 * s);
    }

    O.a = O.r + sin(t) * 0.3;
}

